const vis = phi.js(() => {
  const ps = [...document.querySelectorAll('p')];
  return ps.map(p => {
    const cs = getComputedStyle(p);
    const r = p.getBoundingClientRect();
    return { text: p.textContent.trim(), lang: p.getAttribute('lang') || null, display: cs.display, visibility: cs.visibility, hidden: p.hasAttribute('hidden'), w: Math.round(r.width), h: Math.round(r.height), cls: p.className };
  });
});
return { title: document.title, vis };

