const info = phi.js(() => {
  const out = [];
  for (const el of document.querySelectorAll('body *')) {
    const cs = getComputedStyle(el);
    const r = el.getBoundingClientRect();
    out.push({
      tag: el.tagName,
      cls: el.className && String(el.className).slice(0,60),
      lang: el.getAttribute('lang'),
      text: (el.textContent||'').trim().slice(0,80),
      disp: cs.display, vis: cs.visibility, op: cs.opacity,
      top: Math.round(r.top), h: Math.round(r.height),
      inlineStyle: el.getAttribute('style')
    });
  }
  return { count: out.length, out: out.slice(0, 60), headHTML: document.head.innerHTML.slice(0, 800) };
});
const seen = phi.look();
return info;

const paras = phi.js(() => {
  const ps = [...document.querySelectorAll('p')].map(p => ({ lang: p.getAttribute('lang'), text: p.textContent.trim(), op: getComputedStyle(p).opacity }));
  const heads = [...document.querySelectorAll('h1,h2,h3')].map(h => ({ tag: h.tagName, text: h.textContent.trim() }));
  return { title: document.title, lang: document.documentElement.lang, headings: heads, paras: ps, bodyText: document.body.innerText.trim() };
});
phi.keep("example_page", {
  url: location.href,
  title: paras.title,
  headings: paras.headings,
  firstPara: paras.paras[0],
  englishPara: paras.paras[1],
  allLangs: paras.paras.map(p => p.lang)
});
return { title: paras.title, headings: paras.headings, first: paras.paras[0], english: paras.paras[1], langs: paras.paras.map(p => p.lang) };

const nav = phi.goto("https://example.com/");
const title = phi.js(() => document.title);
const ps = phi.query("p", { limit: 20 });
const heads = phi.query("h1, h2, h3", { limit: 10 });
const anchors = phi.query("a", { limit: 10 });
const fullText = phi.text();
phi.keep("example_page", {
  url: nav.url,
  title,
  headings: heads.items.map(h => h.text),
  paragraphs: ps.items.map(p => p.text),
  links: anchors.items.map(a => a.text),
});
phi.look();
return { title, paraCount: ps.total, paragraphs: ps.items.map(p => p.text), headings: heads.items.map(h => h.text), links: anchors.items.map(a => a.text), visibleText: fullText.slice(0, 1500) };

const p = phi.recall("example_page");
phi.keep("answer", {
  url: p.url,
  title: p.title,
  mainParagraph: p.paragraphs[0],
  englishParagraph: p.paragraphs[1],
  otherLangs: ["ar", "fr", "ru", "es"],
  link: p.links && p.links[0],
  note: "page renders the same notice in 6 languages; the first (full-opacity) paragraph is Chinese, followed by en, ar, fr, ru, es",
});
return { title: p.title, main: p.paragraphs[0], english: p.paragraphs[1], total: p.paragraphs.length };

const vis = phi.js(() => {
  const ps = [...document.querySelectorAll('p')].map(p => {
    const cs = getComputedStyle(p);
    const r = p.getBoundingClientRect();
    return { lang: p.getAttribute('lang'), display: cs.display, vis: cs.visibility, opacity: cs.opacity, h: Math.round(r.height), w: Math.round(r.width), text: p.textContent.trim().slice(0, 120) };
  });
  return { ps, bodyText: document.body.innerText.trim().slice(0, 800) };
});
const seen = phi.readImage(undefined, "Exactly which paragraph text is visible on screen right now? Quote it verbatim.");
return { vis, seen };

const info = phi.js(() => {
  const ps = [...document.querySelectorAll('p')].map((p, i) => {
    const cs = getComputedStyle(p);
    const r = p.getBoundingClientRect();
    return { i, lang: p.getAttribute('lang'), display: cs.display, vis: cs.visibility, opacity: cs.opacity, h: Math.round(r.height), w: Math.round(r.width), text: p.innerText.trim().slice(0, 200) };
  });
  const h1 = document.querySelector('h1');
  return { title: document.title, h1: h1 ? h1.innerText : null, ps, bodyInnerText: document.body.innerText.trim() };
});
phi.look();
return info;

